   *  Adventures". */
  CountdownMarks: number;
  Status: 'Active' | 'Concluded';
  CreatedAt: string;
  UpdatedAt: string;
}

// ---------- Creating the World (V0.6 slice 8) ----------

/** Step 1 of the five-step collaborative map build ("Where the Adventure Begins") —
