import { beforeEach, describe, expect, test, vi } from 'vitest';
import { appendChangeLog } from './repo.js';
import { supabaseAdmin } from './supabase.js';

// Mock the supabase client
vi.mock('./supabase.js');

describe('appendChangeLog', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  test('should insert changelog entry without id field', async () => {
    const mockInsert = vi.fn().mockResolvedValue({ data: null, error: null });
    vi.mocked(supabaseAdmin.from).mockReturnValue({
      insert: mockInsert,
    } as any);

    const entry = {
      Who: 'Test User',
      Action: 'create',
      Collection: 'test',
      ObjectId: 'test-123',
      ObjectName: 'Test Object',
      Before: null,
      After: { test: 'data' },
    };

    await appendChangeLog(entry);

    // Verify that insert was called with the correct data structure
    expect(mockInsert).toHaveBeenCalledWith({
      at: expect.any(String),
      who: 'Test User',
      action: 'create',
      collection: 'test',
      object_id: 'test-123',
      object_name: 'Test Object',
      before: null,
      after: { test: 'data' },
    });

    // Verify that id field is NOT present in the payload
    const insertCall = mockInsert.mock.calls[0][0];
    expect(insertCall).not.toHaveProperty('id');
  });

  test('should throw error when insert fails', async () => {
    const mockError = new Error('Database error');
    const mockInsert = vi.fn().mockResolvedValue({ data: null, error: mockError });
    vi.mocked(supabaseAdmin.from).mockReturnValue({
      insert: mockInsert,
    } as any);

    const entry = {
      Who: 'Test User',
      Action: 'create',
      Collection: 'test',
      ObjectId: 'test-123',
      ObjectName: 'Test Object',
      Before: null,
      After: { test: 'data' },
    };

    await expect(appendChangeLog(entry)).rejects.toThrow('Database error');
  });
});
